// Bundles src/emit.ts and @agent-office/core (with zod) into ONE file with no
// runtime dependencies: dist/agent-office-emit.mjs. Only node: built-ins stay as
// imports. core is bundled from source (alias), so the build does not need core's
// own dist/ to exist.
import { mkdirSync, readFileSync, renameSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { build } from 'esbuild';

const here = dirname(fileURLToPath(import.meta.url));
// First lines of the generated file. `eslint-disable` keeps a host repo's linter
// quiet about this ~20k-line bundle; both lines are plain comments (no shebang).
export const BANNER = [
  '// Generated by Agent Office (packages/emit). Do not edit; re-run the installer.',
  '/* eslint-disable */',
].join('\n');

export const OUTFILE = join(here, 'dist', 'agent-office-emit.mjs');

export async function buildEmit() {
  mkdirSync(dirname(OUTFILE), { recursive: true });
  const result = await build({
    entryPoints: [join(here, 'src', 'emit.ts')],
    outfile: OUTFILE,
    write: false,
    // Fixed root: the `//` path comments in the bundle are the same whatever the
    // caller's cwd, so the copies in other repos can be reproduced byte for byte.
    absWorkingDir: join(here, '..', '..'),
    bundle: true,
    platform: 'node',
    format: 'esm',
    target: 'node22',
    alias: { '@agent-office/core': join(here, '..', 'core', 'src', 'index.ts') },
    banner: { js: BANNER },
    legalComments: 'none',
    logLevel: 'warning',
    tsconfig: join(here, 'tsconfig.json'),
  });
  // Write a temp file then rename, so a reader never sees a half-written bundle
  // (parallel builds and hooks running while the installer rebuilds).
  const tmp = `${OUTFILE}.${process.pid}.${Date.now()}.tmp`;
  writeFileSync(tmp, result.outputFiles[0].contents);
  renameSync(tmp, OUTFILE);
  return OUTFILE;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const out = await buildEmit();
  const kb = Math.round(readFileSync(out).length / 1024);
  process.stdout.write(`built ${out} (${kb} KB)\n`);
}
